import pathlib,subprocess,json,zipfile,hashlib,collections
ROOT=pathlib.Path(__file__).resolve().parents[1]; target='1f559e20b0bd25148571f86f9fb978a2dd0fed0d'; old='9bcd44756cbf5261a0c690e05651e96fa162319a';sha=lambda b:hashlib.sha256(b).hexdigest()
def blob(ref,path):return subprocess.check_output(['git','-C',str(ROOT),'show',ref+':'+path])
def read(path):return json.loads((ROOT/path).read_text())
packet=read('reviews/packets/mathematical-foundation-v1.json');manifest=read(packet['manifest']);archive=ROOT/packet['archive'];assert sha(archive.read_bytes())==packet['archive_sha256'];assert sha((ROOT/packet['manifest']).read_bytes())==packet['manifest_sha256']
with zipfile.ZipFile(archive) as z:
 assert set(z.namelist())=={f['path'] for f in manifest['files']}
 for f in manifest['files']:assert sha(z.read(f['path']))==f['sha256'] and len(z.read(f['path']))==f['bytes']
 original_ledger=json.loads(z.read('census/mathematical-ledger.json'))
 for f in manifest['files']:
  if f['path'].endswith('.lean') and not f['path'].startswith('reports/'):assert blob(target,f['path'])==z.read(f['path']),f['path']
 for path in ['lake-manifest.json','lean-toolchain','census/pilot-value-proofs.json','census/mathematical-corpus-v1.json','census/convolution-ordered-v2.json']:
  assert blob(target,path)==z.read(path),path
all_math=subprocess.check_output(['git','-C',str(ROOT),'ls-tree','-r','--name-only',old],text=True).splitlines();all_math=[p for p in all_math if p.endswith('.lean') and (p.startswith('TensorRewrite/') or p in ['TensorRewrite.lean','TensorRewriteTheory.lean','TensorRewriteLibraries.lean'])]
for path in all_math:assert blob(target,path)==blob(old,path),path
original_review=read('reviews/results/mathematical-foundation-v1-review.json');assert sha((ROOT/'reviews/results/mathematical-foundation-v1-review.json').read_bytes())=='1ddfa3497dcc9e483c6989ffd46af5c58039ad39da855c23f2124200df26d711';assert sha((ROOT/'reviews/results/mathematical-foundation-v1-review.md').read_bytes())=='2a40b3b6a8598fdbfc04dfc971e0eb4c203c63ca3171e45fe8683cd09acd025f'
new=read('census/mathematical-ledger.json');before={p['theorem']:p for p in original_ledger['proofs']};after={p['theorem']:p for p in new['proofs']};expected_added=set(original_review['findings'][0]['affected_declarations']);assert len(after)==349 and set(after)-set(before)==expected_added and len(expected_added)==30 and not set(before)-set(after)
references=collections.defaultdict(list)
def walk(v,path):
 if isinstance(v,dict):
  for k,w in v.items():walk(w,path+'.'+k)
 elif isinstance(v,list):
  for i,w in enumerate(v):walk(w,path+f'[{i}]')
 elif isinstance(v,str) and v.startswith('TensorRewrite.'):references[v].append(path)
walk(read('census/pilot-value-proofs.json'),'pilot');assert len(references)==260 and set(references)<=set(after)
for name,paths in references.items():assert after[name]['retained_manifest_paths']==sorted(paths)
for name,p in before.items():assert after[name]['historical_candidate_benchmark_labels']==p['historical_candidate_benchmark_labels']
for name in expected_added:assert after[name]['historical_candidate_benchmark_labels']==[]
assert all(not p['label_correspondence_certified'] for p in after.values());assert new['benchmark_records']==original_ledger['benchmark_records'];assert new['benchmark_status_counts']==original_ledger['benchmark_status_counts'];assert new['whole_benchmark_records_closed']==0 and new['mathematical_obligation_denominator'] is None and not new['mathematical_denominator_frozen'];assert new['positive_or_negative_workflow_verdict']==original_ledger['positive_or_negative_workflow_verdict']
lib=read('reports/library-setup.json');assert len(lib['axiom_dependencies'])==4 and not set(lib['axiom_dependencies'])&set(after)
addendum=read('census/convolution-ordered-accounting-v1.json')
for key in ['superseded_measurement','category_override_manifest']:
 v=addendum[key];assert sha((ROOT/v['path']).read_bytes())==v['sha256']
assert addendum['new_category_lines']==dict(S=30,H=105,R=93,A=1,C=12);assert addendum['total_custom_category_lines']==dict(S=1131,H=1497,R=1112,A=76,C=349)
override=read('census/lean-category-overrides-v1.json')['files'][0];data=(ROOT/override['path']).read_bytes();assert sha(data)==override['sha256'];assert override['regions']==[dict(first=1,last=55,category='R'),dict(first=56,last=71,category='C'),dict(first=72,last=73,category='R')]
import sys;sys.path.insert(0,str(ROOT/'tools'));from lean_size import count_source
lines=data.decode().splitlines(True);regions=[(r['category'],count_source(''.join(lines[r['first']-1:r['last']]))['code_lines']) for r in override['regions']];assert regions==[('R',39),('C',12),('R',1)]
evidence=read('reviews/results/mathematical-foundation-v1-evidence.json');assert sha((ROOT/evidence['archive']).read_bytes())==evidence['archive_sha256'];assert sha((ROOT/evidence['review']).read_bytes())==evidence['review_sha256']
with zipfile.ZipFile(ROOT/evidence['archive']) as z:
 assert set(z.namelist())=={f['path'] for f in evidence['files']}
 for f in evidence['files']:assert sha(z.read(f['path']))==f['sha256'] and len(z.read(f['path']))==f['bytes']
 for c in original_review['commands_actually_run']:assert sha(z.read(c['log']))==c['log_sha256']
 for c in original_review['additional_lean_commands_actually_run']:assert sha(z.read('review-replay/'+pathlib.Path(c['log']).name))==c['log_sha256']
corrections=read('reports/mathematical-review-corrections-v1.json');cmds=read('reports/mathematical-review-correction-logs-v1/commands.json');assert cmds==[{k:v for k,v in c.items() if k!='log_sha256'} for c in corrections['commands']]
for c in corrections['commands']:assert sha((ROOT/c['log']).read_bytes())==c['log_sha256'] and c['exit_code']==0
result={'target_revision':target,'frozen_archive_sha256':packet['archive_sha256'],'frozen_manifest_sha256':packet['manifest_sha256'],'all_frozen_member_hashes_valid':True,'all_project_math_source_files_unchanged':len(all_math),'original_review_files_unchanged':True,'original_evidence_archive_sha256':evidence['archive_sha256'],'original_evidence_member_count':len(evidence['files']),'archived_correction_logs_valid':len(cmds),'ledger_before':len(before),'ledger_after':len(after),'exact_30_additions':sorted(expected_added),'complete_explicit_pilot_references':len(references),'no_new_labels_or_closure':True,'library_audits_separate':4,'hash_bound_region_counts':regions,'accounting_total':sum(addendum['total_custom_category_lines'].values()),'added_profiles':{name:after[name]['profile_descriptions'] for name in sorted(expected_added)}}
(ROOT/'recheck-logs/independent-integrity.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ['exact_30_additions','added_profiles']},indent=2))
